def balanced_ternary_str(n: int) -> str:
    if n == 0: return '0'
    digits = []
    while n != 0:
        rem = (n % 3 + 3) % 3
        if rem == 0: digits.append('0'); n //= 3
        elif rem == 1: digits.append('+'); n = (n - 1) // 3
        else: digits.append('-'); n = (n + 1) // 3
