def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    n, m = len(source), len(target)
    prev = [j * insert_cost for j in range(m + 1)]
    for i in range(1, n + 1):
        cur = [i * delete_cost] + [0] * m
        for j in range(1, m + 1):
            sub = prev[j - 1] + (0 if source[i - 1] == target[j - 1] else replace_cost)
            cur[j] = min(sub, prev[j] + delete_cost, cur[j - 1] + insert_cost)
        prev = cur
    return prev[m]

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
    out = []
    i = j = 0
    while dp[i][j] > 0:
        for c in sorted(set(a[i:]) & set(b[j:])):
            pi = a.index(c, i)
            pj = b.index(c, j)
            if dp[pi + 1][pj + 1] + 1 == dp[i][j]:
                out.append(c)
                i, j = pi + 1, pj + 1
                break
    return ''.join(out)

def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    INF = float('inf')
    dp = [INF] * (target + 1)
    dp[0] = 0
    for value, limit in zip(coins, limits):
        new = dp[:]
        for t in range(target + 1):
            for c in range(1, limit + 1):
                prev = t - c * value
                if prev < 0:
                    break
                if dp[prev] + c < new[t]:
                    new[t] = dp[prev] + c
        dp = new
    return -1 if dp[target] == INF else dp[target]

def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    inc = [1] * n
    dec = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if nums[j] < nums[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    return max((inc[i] + dec[i] - 1 for i in range(n)), default=0)

import heapq


def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    adj = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
        adj.setdefault(v, []).append((u, w))
    heap = [(0, [start])]
    done = set()
    while heap:
        cost, path = heapq.heappop(heap)
        node = path[-1]
        if node in done:
            continue
        done.add(node)
        if node == goal:
            return (cost, path)
        for nxt, w in adj.get(node, []):
            if nxt not in done:
                heapq.heappush(heap, (cost + w, path + [nxt]))
    return None

def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    adj = [[] for _ in range(n)]
    for idx, (u, v) in enumerate(edges):
        adj[u].append((v, idx))
        adj[v].append((u, idx))
    disc = [-1] * n
    low = [0] * n
    bridges = []
    timer = 0
    for root in range(n):
        if disc[root] != -1:
            continue
        disc[root] = low[root] = timer
        timer += 1
        stack = [(root, -1, iter(adj[root]))]
        while stack:
            node, parent_edge, it = stack[-1]
            advanced = False
            for nxt, idx in it:
                if idx == parent_edge:
                    continue
                if disc[nxt] == -1:
                    disc[nxt] = low[nxt] = timer
                    timer += 1
                    stack.append((nxt, idx, iter(adj[nxt])))
                    advanced = True
                    break
                low[node] = min(low[node], disc[nxt])
            if not advanced:
                stack.pop()
                if stack:
                    parent = stack[-1][0]
                    low[parent] = min(low[parent], low[node])
                    if low[node] > disc[parent]:
                        bridges.append((min(parent, node), max(parent, node)))
    return sorted(bridges)

from collections import deque


def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    adj = [set() for _ in range(n)]
    for u, v in edges:
        if u != v:
            adj[u].add(v)
            adj[v].add(u)
    dist = [-1] * n
    ways = [0] * n
    dist[source] = 0
    ways[source] = 1
    queue = deque([source])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
            if dist[v] == dist[u] + 1:
                ways[v] += ways[u]
    return ways[target]

def evaluate_expression(expr: str) -> int:
    s = expr.replace(' ', '')
    pos = 0

    def peek() -> str:
        return s[pos] if pos < len(s) else ''

    def parse_sum() -> int:
        nonlocal pos
        value = parse_term()
        while peek() in ('+', '-'):
            op = s[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term() -> int:
        nonlocal pos
        value = parse_unary()
        while peek() in ('*', '/'):
            op = s[pos]
            pos += 1
            rhs = parse_unary()
            if op == '*':
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError('division by zero')
                q = abs(value) // abs(rhs)
                value = q if (value < 0) == (rhs < 0) else -q
        return value

    def parse_unary() -> int:
        nonlocal pos
        if peek() == '-':
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power() -> int:
        nonlocal pos
        base = parse_atom()
        if peek() == '^':
            pos += 1
            return base ** parse_power()
        return base

    def parse_atom() -> int:
        nonlocal pos
        if peek() == '(':
            pos += 1
            value = parse_sum()
            pos += 1  # the closing parenthesis
            return value
        start = pos
        while pos < len(s) and s[pos].isdigit():
            pos += 1
        return int(s[start:pos])

    return parse_sum()

def parse_csv(text: str) -> list[list[str]]:
    records = []
    row = []
    field = []
    in_quotes = False
    pending = False
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        pending = True
        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(ch)
        elif ch == '"':
            in_quotes = True
        elif ch == ',':
            row.append(''.join(field))
            field = []
        elif ch == '\n':
            row.append(''.join(field))
            field = []
            records.append(row)
            row = []
            pending = False
        else:
            field.append(ch)
        i += 1
    if pending:
        row.append(''.join(field))
        records.append(row)
    return records

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    n = len(source)
    two = ('==', '!=', '<=', '>=')
    one = '+-*/<>=(),'
    while i < n:
        ch = source[i]
        if ch in ' \t\n':
            i += 1
        elif '0' <= ch <= '9':
            j = i
            while j < n and '0' <= source[j] <= '9':
                j += 1
            if j + 1 < n and source[j] == '.' and '0' <= source[j + 1] <= '9':
                j += 1
                while j < n and '0' <= source[j] <= '9':
                    j += 1
            tokens.append(('NUMBER', source[i:j]))
            i = j
        elif ch == '_' or 'a' <= ch <= 'z' or 'A' <= ch <= 'Z':
            j = i
            while j < n and (source[j] == '_' or 'a' <= source[j] <= 'z' or 'A' <= source[j] <= 'Z'
                             or '0' <= source[j] <= '9'):
                j += 1
            tokens.append(('NAME', source[i:j]))
            i = j
        elif source[i:i + 2] in two:
            tokens.append(('OP', source[i:i + 2]))
            i += 2
        elif ch in one:
            tokens.append(('OP', ch))
            i += 1
        else:
            raise ValueError('unexpected character ' + repr(ch))
    return tokens

from collections import OrderedDict


def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []
    for op in operations:
        if op[0] == 'put':
            _, key, value = op
            if capacity <= 0:
                continue
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        else:
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(None)
    return (results, list(cache.keys()))

def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0
    steps = 0

    def need(k: int) -> None:
        if len(stack) < k:
            raise ValueError('stack underflow')

    while 0 <= pc < len(program):
        steps += 1
        if steps > 1000:
            raise RuntimeError('too many steps')
        parts = program[pc].split()
        op = parts[0] if parts else ''
        pc += 1
        if op == 'PUSH':
            stack.append(int(parts[1]))
        elif op == 'POP':
            need(1)
            stack.pop()
        elif op == 'DUP':
            need(1)
            stack.append(stack[-1])
        elif op == 'SWAP':
            need(2)
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op in ('ADD', 'SUB', 'MUL'):
            need(2)
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b if op == 'ADD' else a - b if op == 'SUB' else a * b)
        elif op == 'JMP':
            pc = int(parts[1])
        elif op == 'JZ':
            need(1)
            if stack.pop() == 0:
                pc = int(parts[1])
        elif op == 'HALT':
            break
        else:
            raise ValueError('unknown instruction: ' + program[pc - 1])
    return stack

from datetime import date, timedelta


def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    current = date.fromisoformat(start)
    off = {date.fromisoformat(h) for h in holidays}
    step = 1 if n > 0 else -1
    remaining = abs(n)
    while remaining:
        current += timedelta(days=step)
        if current.weekday() < 5 and current not in off:
            remaining -= 1
    return current.isoformat()

def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ''
    widths = [max(len(row[c]) for row in rows) for c in range(len(aligns))]
    lines = []
    for row in rows:
        cells = []
        for c, mode in enumerate(aligns):
            cell = row[c]
            pad = widths[c] - len(cell)
            if mode == 'r':
                cells.append(' ' * pad + cell)
            elif mode == 'c':
                left = pad // 2
                cells.append(' ' * left + cell + ' ' * (pad - left))
            else:
                cells.append(cell + ' ' * pad)
        lines.append(' | '.join(cells))
    return '\n'.join(lines)

from collections import deque


def min_slides(grid: list[str]) -> int:
    h, w = len(grid), len(grid[0])
    start = goal = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                goal = (r, c)
    dist = {start: 0}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        if (r, c) == goal:
            return dist[(r, c)]
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r, c
            while 0 <= nr + dr < h and 0 <= nc + dc < w and grid[nr + dr][nc + dc] != '#':
                nr += dr
                nc += dc
            if (nr, nc) != (r, c) and (nr, nc) not in dist:
                dist[(nr, nc)] = dist[(r, c)] + 1
                queue.append((nr, nc))
    return -1

def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    def mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        return [[sum(a[i][t] * b[t][j] for t in range(n)) % mod for j in range(n)] for i in range(n)]

    result = [[(1 if i == j else 0) % mod for j in range(n)] for i in range(n)]
    base = [[x % mod for x in row] for row in matrix]
    while exp > 0:
        if exp & 1:
            result = mul(result, base)
        base = mul(base, base)
        exp >>= 1
    return result

def expand_template(template: str, values: dict[str, str]) -> str:
    out = []
    i = 0
    n = len(template)
    while i < n:
        if template.startswith('{{', i):
            out.append('{')
            i += 2
        elif template.startswith('}}', i):
            out.append('}')
            i += 2
        elif template[i] == '{':
            j = template.find('}', i + 1)
            if j == -1:
                out.append('{')
                i += 1
            else:
                key = template[i + 1:j]
                if key in values:
                    out.append(values[key])
                else:
                    out.append(template[i:j + 1])
                i = j + 1
        else:
            out.append(template[i])
            i += 1
    return ''.join(out)

def decode_runs(encoded: str) -> str:
    out = []
    i = 0
    n = len(encoded)
    while i < n:
        if encoded[i] == '\\':
            ch = encoded[i + 1]
            i += 2
        else:
            ch = encoded[i]
            i += 1
        if i < n and encoded[i] == '~':
            i += 1
            j = i
            while j < n and encoded[j] in '0123456789':
                j += 1
            out.append(ch * int(encoded[i:j]))
            i = j
        else:
            out.append(ch)
    return ''.join(out)

import re


def tidy_punctuation(text: str) -> str:
    s = ' '.join(text.split())
    s = re.sub(r' (?=[,.;:!?])', '', s)
    s = re.sub(r'([,.;:!?])(?=[A-Za-z])', r'\1 ', s)
    chars = list(s)
    if chars:
        chars[0] = chars[0].upper()
    for i in range(2, len(chars)):
        if chars[i - 1] == ' ' and chars[i - 2] in '.!?':
            chars[i] = chars[i].upper()
    return ''.join(chars)

def identifier_to_snake(name: str) -> str:
    words = []
    for piece in name.replace('-', '_').split('_'):
        if not piece:
            continue
        cur = piece[0]
        for i in range(1, len(piece)):
            p, c = piece[i - 1], piece[i]
            nxt = piece[i + 1] if i + 1 < len(piece) else ''
            if p.islower() and c.isupper():
                split = True
            elif p.isalpha() != c.isalpha():
                split = True
            elif p.isupper() and c.isupper() and nxt.islower():
                split = True
            else:
                split = False
            if split:
                words.append(cur)
                cur = c
            else:
                cur += c
        words.append(cur)
    return '_'.join(w.lower() for w in words)

def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []
    clipped = []
    for s, e in busy:
        if s < e:
            s2, e2 = max(s, day_start), min(e, day_end)
            if s2 < e2:
                clipped.append((s2, e2))
    clipped.sort()
    result = []
    cur = day_start
    for s, e in clipped:
        if s > cur and s - cur >= min_len:
            result.append((cur, s))
        cur = max(cur, e)
    if day_end > cur and day_end - cur >= min_len:
        result.append((cur, day_end))
    return result

