def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    bad = {(r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n}
    cols = set()
    d1 = set()
    d2 = set()

    def rec(r):
        if r == n:
            return 1
        total = 0
        for c in range(n):
            if c in cols or (r - c) in d1 or (r + c) in d2 or (r, c) in bad:
                continue
            cols.add(c)
            d1.add(r - c)
            d2.add(r + c)
            total += rec(r + 1)
            cols.remove(c)
            d1.remove(r - c)
            d2.remove(r + c)
        return total

    return rec(0)

