def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    bal = dict(balances)
    frozen = set()
    failed = []
    for idx, op in enumerate(ops):
        kind = op[0]
        ok = False
        if kind == 'deposit':
            _, acc, amt = op
            if acc in bal and amt > 0 and acc not in frozen:
                bal[acc] += amt
                ok = True
        elif kind == 'withdraw':
            _, acc, amt = op
            if acc in bal and amt > 0 and acc not in frozen and bal[acc] >= amt:
                bal[acc] -= amt
                ok = True
        elif kind == 'transfer':
            _, src, dst, amt = op
            if (src in bal and dst in bal and src != dst and amt > 0
                    and src not in frozen and dst not in frozen and bal[src] >= amt + 2):
                bal[src] -= amt + 2
                bal[dst] += amt
                ok = True
        elif kind == 'freeze':
            if op[1] in bal:
                frozen.add(op[1])
                ok = True
        elif kind == 'unfreeze':
            if op[1] in bal:
                frozen.discard(op[1])
                ok = True
        if not ok:
            failed.append(idx)
    return bal, failed

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    queues = {}
    for seq, (kind, item, qty) in enumerate(events):
        stock.setdefault(item, 0)
        queue = queues.setdefault(item, [])
        if kind == 'receive':
            stock[item] += qty
            while queue and queue[0][1] <= stock[item]:
                stock[item] -= queue.pop(0)[1]
        elif kind == 'order':
            if not queue and stock[item] >= qty:
                stock[item] -= qty
            else:
                queue.append((seq, qty))
    pending = sorted((seq, item, qty) for item, q in queues.items() for seq, qty in q)
    return stock, [(item, qty) for _, item, qty in pending]

def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    steps = 0
    n = len(program)
    while ip < n:
        if steps >= 1000:
            return None
        steps += 1
        parts = program[ip].split()
        op = parts[0]
        ip += 1
        if op == 'PUSH':
            stack.append(int(parts[1]))
        elif op == 'POP':
            if not stack:
                return None
            stack.pop()
        elif op == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op in ('ADD', 'SUB', 'MUL'):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if op == 'ADD':
                stack.append(a + b)
            elif op == 'SUB':
                stack.append(a - b)
            else:
                stack.append(a * b)
        elif op == 'JMP':
            ip = int(parts[1])
        elif op == 'JZ':
            if not stack:
                return None
            if stack.pop() == 0:
                ip = int(parts[1])
    return stack

def convert_base(number: str, from_base: int, to_base: int) -> str:
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    s = number
    negative = False
    if s.startswith('-'):
        negative = True
        s = s[1:]
    if not s:
        raise ValueError('no digits')
    value = 0
    for ch in s:
        d = digits.find(ch.lower()) if len(ch.lower()) == 1 else -1
        if d < 0 or d >= from_base:
            raise ValueError('invalid digit')
        value = value * from_base + d
    if value == 0:
        return '0'
    out = []
    while value:
        value, r = divmod(value, to_base)
        out.append(digits[r])
    text = ''.join(reversed(out))
    return '-' + text if negative else text

def count_set_bits_range(lo: int, hi: int) -> int:
    def upto(n):
        # total number of 1 bits in 0..n inclusive (n >= -1)
        if n < 0:
            return 0
        count = n + 1
        total = 0
        bit = 0
        while (1 << bit) <= n:
            cycle = 1 << (bit + 1)
            total += (count // cycle) * (1 << bit)
            total += max(0, count % cycle - (1 << bit))
            bit += 1
        return total

    if lo > hi:
        return 0
    return upto(hi) - upto(lo - 1)

