from collections import deque


def shortest_path_one_break(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    start = end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)
    seen = {(start[0], start[1], 0)}
    queue = deque([(start[0], start[1], 0, 0)])
    while queue:
        r, c, used, dist = queue.popleft()
        if (r, c) == end:
            return dist
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nused = used + (1 if grid[nr][nc] == '#' else 0)
                if nused <= 1 and (nr, nc, nused) not in seen:
                    seen.add((nr, nc, nused))
                    queue.append((nr, nc, nused, dist + 1))
    return -1

def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    g = [list(row) for row in grid]
    rows = len(g)
    stack = [(r, c) for r in range(rows) for c in range(len(g[r]))]
    while stack:
        r, c = stack.pop()
        if g[r][c] < 4:
            continue
        k = g[r][c] // 4
        g[r][c] -= 4 * k
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(g[nr]):
                g[nr][nc] += k
                if g[nr][nc] >= 4:
                    stack.append((nr, nc))
    return g
